def logo_bytes(which: str = "blanc") -> bytes:
    import base64
    return base64.b64decode({"blanc": LOGO_BLANC_B64, "noir": LOGO_NOIR_B64, "icone": ICONE_B64,
                             "noir_jpg": LOGO_NOIR_JPG_B64}[which])


def logo_pil(which: str = "blanc"):
    from io import BytesIO
    from PIL import Image
    return Image.open(BytesIO(logo_bytes(which)))


