# =============================================================================
# OUTILS (dates, nombres, euros)
# =============================================================================
def today_iso() -> str:
    return date.today().isoformat()


def iso_to_fr(s: str) -> str:
    if not s:
        return ""
    try:
        return datetime.strptime(s[:10], "%Y-%m-%d").strftime("%d/%m/%Y")
    except ValueError:
        return s


def fr_to_iso(s: str) -> str:
    """Accepte 26/10/2026, 26/10/26, 26-10-2026 ou 2026-10-26. Lève ValueError si invalide."""
    s = (s or "").strip()
    if not s:
        return ""
    for fmt in ("%d/%m/%Y", "%d/%m/%y", "%d-%m-%Y", "%d.%m.%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            continue
    raise ValueError(f"Date invalide : {s} (format attendu JJ/MM/AAAA)")


def to_float(s: Any, default: Optional[float] = None) -> Optional[float]:
    if isinstance(s, (int, float)):
        f = float(s)
        return f if f == f and f not in (float("inf"), float("-inf")) else default   # NaN (case vide) → défaut
    txt = str(s or "").replace("€", "").replace(" ", "").replace(" ", "").replace(",", ".").strip()
    if txt.endswith("m"):
        txt = txt[:-1]
    if not txt:
        return default
    try:
        return float(txt)
    except ValueError:
        return default


def eur(x: Optional[float], signed: bool = False) -> str:
    if x is None:
        return "—"
    s = f"{abs(x):,.2f}".replace(",", " ").replace(".", ",")
    if signed:
        return ("+" if x >= 0 else "−") + s + " €"
    return ("−" if x < 0 else "") + s + " €"


def num(x: float, dec: int = 2) -> str:
    return f"{x:.{dec}f}".replace(".", ",")


def new_id(prefix: str) -> str:
    return f"{prefix}-{datetime.now().strftime('%Y%m%d%H%M%S%f')}"


MOIS_COURTS = ["janv.", "févr.", "mars", "avr.", "mai", "juin", "juil.", "août", "sept.", "oct.", "nov.", "déc."]


# =============================================================================
# LOGIQUE MÉTIER : CLIENTS, ROULEAUX, STATISTIQUES
# =============================================================================
def normalize_client(c: Dict[str, Any]) -> Dict[str, Any]:
    """Complète une fiche (y compris les anciennes) avec tous les champs attendus."""
    out = {
        "id": c.get("id") or new_id("cli"),
        "clientNom": c.get("clientNom", ""),
        "telephone": c.get("telephone", ""),
        "contact": c.get("contact", ""),               # Instagram / email
        "vehicule": c.get("vehicule", ""),
        "immatriculation": c.get("immatriculation", ""),
        "pack": c.get("pack", PRESTATIONS[0]),
        "teinte": c.get("teinte", ""),
        "rouleauId": c.get("rouleauId", ""),
        "metrageUtiliseM": float(c.get("metrageUtiliseM", 0) or 0),
        "prixFactureTTC": float(c.get("prixFactureTTC", 0) or 0),
        "reglement": c.get("reglement", ""),
        "statutPaiement": c.get("statutPaiement", "Payé" if c.get("prixFactureTTC") else "À encaisser"),
        "statut": c.get("statut", "Posé"),
        "source": c.get("source", ""),
        "parrain": c.get("parrain", ""),
        "dateDevis": c.get("dateDevis", ""),
        "dateRdv": c.get("dateRdv", ""),
        "datePose": c.get("datePose", ""),
        "avisDemande": bool(c.get("avisDemande", False)),
        "categorie": c.get("categorie", ""),            # "D" ou "PAD"
        "notes": c.get("notes", ""),
        "coutRevientTTC": float(c.get("coutRevientTTC", 0) or 0),   # utilisé seulement sans rouleau lié
    }
    return out


def normalize_roll(r: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "id": r.get("id") or new_id("rlx"),
        "marque": r.get("marque", "Lexen"),
        "reference": r.get("reference", ""),
        "teinte": r.get("teinte", ""),
        "laize_cm": float(r.get("laize_cm", 101) or 0),
        "longueur_m": float(r.get("longueur_m", 30) or 0),
        "prix_achat_ttc": float(r.get("prix_achat_ttc", 0) or 0),
        "date_achat": r.get("date_achat", ""),
        "fournisseur": r.get("fournisseur", ""),
        "statut": r.get("statut", "En cours"),
        "date_fin": r.get("date_fin", ""),
        "notes": r.get("notes", ""),
    }


def roll_cost_per_m(r: Dict[str, Any]) -> float:
    return r["prix_achat_ttc"] / r["longueur_m"] if r.get("longueur_m") else 0.0


def roll_title(r: Dict[str, Any]) -> str:
    parts = [r.get("marque", "")]
    if r.get("reference"):
        parts.append(r["reference"])
    if r.get("teinte"):
        parts.append(r["teinte"])
    return " ".join(p for p in parts if p).strip() or "Rouleau"


def roll_choices(rolls: List[Dict[str, Any]], only_active: bool = False) -> List[Tuple[str, str]]:
    """Liste (libellé unique, id) pour les menus déroulants."""
    out, seen = [], {}
    ordered = sorted(rolls, key=lambda r: (r["statut"] != "En cours", r.get("date_achat", "")), reverse=False)
    for r in ordered:
        if only_active and r["statut"] != "En cours":
            continue
        label = f"{roll_title(r)} • {r['laize_cm']:.0f} cm"
        if r.get("date_achat"):
            label += f" • {iso_to_fr(r['date_achat'])}"
        if r["statut"] != "En cours":
            label += " (terminé)"
        n = seen.get(label, 0)
        seen[label] = n + 1
        if n:
            label += f" #{n + 1}"
        out.append((label, r["id"]))
    return out


def client_cost(c: Dict[str, Any], rolls_by_id: Dict[str, Dict[str, Any]]) -> float:
    r = rolls_by_id.get(c.get("rouleauId", ""))
    if r:
        return round(c["metrageUtiliseM"] * roll_cost_per_m(r), 2)
    return round(c.get("coutRevientTTC", 0.0), 2)


def is_done(c: Dict[str, Any]) -> bool:
    return c.get("statut") == "Posé"


def roll_stats(r: Dict[str, Any], clients: List[Dict[str, Any]]) -> Dict[str, Any]:
    linked = [c for c in clients if c.get("rouleauId") == r["id"] and is_done(c)]
    nb = len(linked)
    used = sum(c["metrageUtiliseM"] for c in linked)
    restant = max(0.0, r["longueur_m"] - used)
    avg_m = used / nb if nb else 0.0
    ca = sum(c["prixFactureTTC"] for c in linked)
    return {
        "nb_vehicules": nb,
        "metres_utilises": used,
        "metres_restants": restant,
        "pct": min(1.0, used / r["longueur_m"]) if r["longueur_m"] else 0.0,
        "metrage_moyen": avg_m,
        "vehicules_restants": int(restant // avg_m) if avg_m > 0 else None,
        "projection_total": (nb + int(restant // avg_m)) if avg_m > 0 else None,
        # Rouleau terminé : prix réel ÷ véhicules. En cours : estimation sur le métrage consommé.
        "cout_reel_par_vehicule": ((r["prix_achat_ttc"] / nb) if r.get("statut") == "Terminé"
                                   else (used * roll_cost_per_m(r) / nb)) if nb else None,
        "ca": ca,
        "resultat": ca - r["prix_achat_ttc"],
        "cout_m": roll_cost_per_m(r),
    }


def global_roll_stats(rolls: List[Dict[str, Any]], clients: List[Dict[str, Any]]) -> Dict[str, Any]:
    stats = {r["id"]: roll_stats(r, clients) for r in rolls}
    finished = [r for r in rolls if r["statut"] == "Terminé"]
    if finished:
        moy_veh = sum(stats[r["id"]]["nb_vehicules"] for r in finished) / len(finished)
        moy_label = f"sur {len(finished)} rouleau{'x' if len(finished) > 1 else ''} terminé{'s' if len(finished) > 1 else ''}"
        cout_moy = sum(r["prix_achat_ttc"] for r in finished) / max(1, sum(stats[r["id"]]["nb_vehicules"] for r in finished))
    else:
        proj = [stats[r["id"]]["projection_total"] for r in rolls if stats[r["id"]]["projection_total"]]
        moy_veh = sum(proj) / len(proj) if proj else None
        moy_label = "projection (aucun rouleau terminé)" if proj else "pas encore de données"
        done_linked = [c for c in clients if is_done(c) and c.get("rouleauId") in stats]
        rb = {r["id"]: r for r in rolls}
        cout_moy = (sum(client_cost(c, rb) for c in done_linked) / len(done_linked)) if done_linked else None
    linked_done = [c for c in clients if is_done(c) and c.get("rouleauId")]
    met_moy = sum(c["metrageUtiliseM"] for c in linked_done) / len(linked_done) if linked_done else None
    tot_len = sum(r["longueur_m"] for r in rolls)
    prix_m_moy = sum(r["prix_achat_ttc"] for r in rolls) / tot_len if tot_len else None
    return {
        "par_rouleau": stats,
        "moyenne_vehicules": moy_veh,
        "moyenne_label": moy_label,
        "metrage_moyen": met_moy,
        "cout_moyen_vehicule": cout_moy,
        "prix_m_moyen": prix_m_moy,
        "depenses": sum(r["prix_achat_ttc"] for r in rolls),
    }


def dashboard_stats(clients, rolls, settings) -> Dict[str, Any]:
    rb = {r["id"]: r for r in rolls}
    done = [c for c in clients if is_done(c)]
    today = date.today()
    month_key = today.strftime("%Y-%m")
    ca_total = sum(c["prixFactureTTC"] for c in done)
    cout_total = sum(client_cost(c, rb) for c in done)
    ca_mois = sum(c["prixFactureTTC"] for c in done if (c.get("datePose") or "").startswith(month_key))
    nb_mois = sum(1 for c in done if (c.get("datePose") or "").startswith(month_key))

    # 6 derniers mois
    months = []
    y, m = today.year, today.month
    for _ in range(6):
        months.append((y, m))
        m -= 1
        if m == 0:
            y, m = y - 1, 12
    months.reverse()
    ca_par_mois = []
    for (yy, mm) in months:
        key = f"{yy:04d}-{mm:02d}"
        ca_par_mois.append((MOIS_COURTS[mm - 1], sum(c["prixFactureTTC"] for c in done if (c.get("datePose") or "").startswith(key))))

    delai = int(settings.get("delai_relance_jours", 3))
    a_relancer = []
    for c in clients:
        if c["statut"] == "Devis envoyé":
            d = c.get("dateDevis")
            try:
                age = (today - date.fromisoformat(d)).days if d else delai
            except ValueError:
                age = delai
            if age >= delai:
                a_relancer.append((c, age))
    a_relancer.sort(key=lambda t: -t[1])

    rdv = []
    for c in clients:
        if c["statut"] == "RDV fixé" and c.get("dateRdv"):
            try:
                if date.fromisoformat(c["dateRdv"]) >= today:
                    rdv.append(c)
            except ValueError:
                pass
    rdv.sort(key=lambda c: c["dateRdv"])

    a_encaisser = [c for c in done if c.get("statutPaiement") in ("À encaisser", "Acompte versé")]
    avis = [c for c in done if not c.get("avisDemande")]

    sources: Dict[str, int] = {}
    for c in clients:
        if c["statut"] != "Perdu" and c.get("source"):
            sources[c["source"]] = sources.get(c["source"], 0) + 1

    devis_total = sum(1 for c in clients if c["statut"] in ("Devis envoyé", "RDV fixé", "Posé", "Perdu"))
    gagnes = sum(1 for c in clients if c["statut"] in ("RDV fixé", "Posé"))

    return {
        "ca_total": ca_total,
        "benef_total": ca_total - cout_total,
        "ca_mois": ca_mois,
        "nb_mois": nb_mois,
        "nb_poses": len(done),
        "panier_moyen": ca_total / len(done) if done else 0.0,
        "ca_par_mois": ca_par_mois,
        "a_relancer": a_relancer,
        "rdv": rdv,
        "a_encaisser": a_encaisser,
        "avis": avis,
        "sources": sorted(sources.items(), key=lambda t: -t[1]),
        "taux_transfo": (gagnes / devis_total) if devis_total else None,
    }


# =============================================================================
# MOTEUR TECHNIQUE : SENS DU FILM STRICTEMENT HORIZONTAL
# =============================================================================
class StrictHorizontalNestingEngine:
    """
    Règle impérative de pose automobile : Le film s'utilise uniquement à l'horizontale.
    - Hauteur vitre alignée sur la Laize.
    - Largeur vitre alignée sur la Longueur du rouleau.
    - Zéro rotation à 90° autorisée.
    """

    @staticmethod
    def compute(vitres: List[Dict[str, Any]], laize_cm: float = 76.0, marge_cm: float = 5.0):
        active_items = [v for v in vitres if v.get("included", True)]
        if not active_items:
            return {
                "placed": [],
                "unfitted": [],
                "total_linear_cm": 0,
                "total_linear_m": 0.0,
                "surface_used_m2": 0.0,
                "surface_cut_m2": 0.0,
                "efficiency_pct": 0.0,
                "has_seam_warning": False
            }

        candidates = []
        for v in active_items:
            raw_h = float(v["hauteur_cm"])
            raw_w = float(v["largeur_cm"])
            h_laize = max(1.0, raw_h + marge_cm)
            w_roll = max(1.0, raw_w + marge_cm)
            fits = h_laize <= laize_cm
            candidates.append({
                "raw": v,
                "h_laize": h_laize,
                "w_roll": w_roll,
                "fits": fits,
                "exceeds_by": max(0.0, h_laize - laize_cm)
            })

        candidates.sort(key=lambda x: (x["h_laize"], x["w_roll"]), reverse=True)

        stripes = []
        placed = []
        unfitted = []
        has_seam_warning = False

        for c in candidates:
            h_laize = c["h_laize"]
            w_roll = c["w_roll"]
            v = c["raw"]

            if not c["fits"]:
                has_seam_warning = True
                unfitted.append({
                    "nom": v.get("nom", "Vitre"),
                    "zone": v.get("zone", "arriere"),
                    "h_laize": h_laize,
                    "w_roll": w_roll,
                    "exceeds_by": c["exceeds_by"]
                })

                start_y = sum(s["length"] for s in stripes)
                stripes.append({
                    "y": start_y,
                    "length": w_roll,
                    "used_laize": laize_cm
                })

                placed.append({
                    "nom": v.get("nom", "Vitre"),
                    "zone": v.get("zone", "arriere"),
                    "x": 0.0,
                    "y": start_y,
                    "height_on_laize": h_laize,
                    "width_on_roll": w_roll,
                    "raw_h": v["hauteur_cm"],
                    "raw_w": v["largeur_cm"],
                    "fits": False,
                    "exceeds_by": c["exceeds_by"]
                })
                continue

            best_stripe_idx = -1
            min_leftover = float("inf")

            for s_idx, stripe in enumerate(stripes):
                remaining_laize = laize_cm - stripe["used_laize"]
                if remaining_laize >= h_laize:
                    leftover = remaining_laize - h_laize
                    if leftover < min_leftover:
                        min_leftover = leftover
                        best_stripe_idx = s_idx

            if best_stripe_idx != -1:
                stripe = stripes[best_stripe_idx]
                placed.append({
                    "nom": v.get("nom", "Vitre"),
                    "zone": v.get("zone", "arriere"),
                    "x": stripe["used_laize"],
                    "y": stripe["y"],
                    "height_on_laize": h_laize,
                    "width_on_roll": w_roll,
                    "raw_h": v["hauteur_cm"],
                    "raw_w": v["largeur_cm"],
                    "fits": True,
                    "exceeds_by": 0.0
                })
                stripe["used_laize"] += h_laize
                stripe["length"] = max(stripe["length"], w_roll)
            else:
                start_y = sum(s["length"] for s in stripes)
                stripes.append({
                    "y": start_y,
                    "length": w_roll,
                    "used_laize": h_laize
                })
                placed.append({
                    "nom": v.get("nom", "Vitre"),
                    "zone": v.get("zone", "arriere"),
                    "x": 0.0,
                    "y": start_y,
                    "height_on_laize": h_laize,
                    "width_on_roll": w_roll,
                    "raw_h": v["hauteur_cm"],
                    "raw_w": v["largeur_cm"],
                    "fits": True,
                    "exceeds_by": 0.0
                })

        total_linear_cm = sum(s["length"] for s in stripes)
        total_linear_m = round(total_linear_cm / 100.0, 2)
        total_used_cm2 = total_linear_cm * laize_cm
        cut_area_cm2 = sum(p["height_on_laize"] * p["width_on_roll"] for p in placed)
        eff_pct = round((cut_area_cm2 / total_used_cm2 * 100.0), 1) if total_used_cm2 > 0 else 0.0

        return {
            "placed": placed,
            "unfitted": unfitted,
            "total_linear_cm": total_linear_cm,
            "total_linear_m": total_linear_m,
            "surface_used_m2": round(total_used_cm2 / 10000.0, 3),
            "surface_cut_m2": round(cut_area_cm2 / 10000.0, 3),
            "efficiency_pct": eff_pct,
            "has_seam_warning": has_seam_warning
        }


# =============================================================================
# ESTIMATION IA GEMINI
# =============================================================================
class GeminiEstimator:
    @staticmethod
    def estimate(marque: str, modele: str, annee: str = "") -> Dict[str, Any]:
        api_key = os.environ.get("GEMINI_API_KEY", "").strip()
        if not api_key:
            raise ValueError("Clé API absente. Mode local actif.")

        url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={api_key}"

        system_instruction = (
            "Tu es un métreur automobile expert en pose de films solaires pour 'Wrad'.\n"
            "RÈGLES STRICTES :\n"
            "1. AUCUN PARE-BRISE ne doit être inclus.\n"
            "2. Liste toutes les vitres (Lunette arrière, vitres latérales arrière, custodes arrière, vitres avant, custodes avant).\n"
            "3. Règle technique : la hauteur s'aligne sur la laize et la largeur sur la longueur.\n"
            "4. Format JSON pur obligatoire :\n"
            '{"generation": "string", "vitres": [{"nom": "string", "hauteur_cm": int, "largeur_cm": int, "zone": "avant" | "arriere"}]}'
        )

        prompt = f"Véhicule : {marque} {modele} {annee or 'récent'}. Dimensions réelles nettes en cm."
        payload = {
            "contents": [{"parts": [{"text": prompt}]}],
            "systemInstruction": {"parts": [{"text": system_instruction}]},
            "generationConfig": {"responseMimeType": "application/json", "temperature": 0.2}
        }

        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers={"Content-Type": "application/json"})

        with urllib.request.urlopen(req, timeout=12) as response:
            res_body = response.read().decode("utf-8")
            res_json = json.loads(res_body)
            raw_text = res_json.get("candidates", [])[0].get("content", {}).get("parts", [{}])[0].get("text", "")
            parsed = json.loads(raw_text)
            vitres = parsed.get("vitres", [])
            clean_vitres = []
            for v in vitres:
                zone = "avant" if "av" in str(v.get("zone", "")).lower() else "arriere"
                clean_vitres.append({
                    "nom": str(v.get("nom", "Vitre")),
                    "hauteur_cm": int(v.get("hauteur_cm", 45)),
                    "largeur_cm": int(v.get("largeur_cm", 60)),
                    "zone": zone,
                    "included": True
                })
            return {"generation": parsed.get("generation", "Estimé par IA"), "vitres": clean_vitres}


# =============================================================================
# GÉNÉRATEUR DE DEVIS PDF ÉPURÉ & PROFESSIONNEL (WRAD)
# =============================================================================
class WradPDFGenerator:
    """
    Générateur de devis PDF épuré pour l'atelier Wrad.
    Suppression stricte des éléments superflus :
    - Aucun slogan 'automotive tinting'
    - Aucune description 'pose de films solaire haut de gamme & sécurité automobile'
    - Aucun bloc argumentaire (Esthétique, Confort thermique, Intimité, Protection 99% UV)
    - Aucun bloc 'Engagements & Réglementations'
    - Aucune mention 'Validité de l'offre'
    Concentré uniquement sur l'essentiel : en-tête Wrad, coordonnées, véhicule,
    tableau des prestations avec métrages et totaux financiers.
    """

    @staticmethod
    def generate_pdf(
        filepath: str,
        devis_num: str,
        date_str: str,
        vehicule: Dict[str, Any],
        prestation_title: str,
        prestation_desc: str,
        metrage_m: float,
        prix_ttc: float,
        roll_nom: str = "",
        laize_cm: float = 76.0,
        client_nom: str = ""
    ) -> bool:
        """
        Génère un fichier PDF natif vectoriel via ReportLab si disponible.
        """
        try:
            from reportlab.lib.pagesizes import A4
            from reportlab.lib import colors
            from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
            from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
            from reportlab.lib.units import cm

            doc = SimpleDocTemplate(
                filepath,
                pagesize=A4,
                rightMargin=2 * cm,
                leftMargin=2 * cm,
                topMargin=2 * cm,
                bottomMargin=2 * cm
            )

            styles = getSampleStyleSheet()
            red_wrad = colors.HexColor("#E10600")
            dark_bg = colors.HexColor("#121215")
            light_gray = colors.HexColor("#F4F4F5")
            border_gray = colors.HexColor("#E4E4E7")
            text_dark = colors.HexColor("#18181B")
            text_muted = colors.HexColor("#71717A")

            # Styles personnalisés épurés
            title_style = ParagraphStyle(
                'WradTitle',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=26,
                leading=30,
                textColor=colors.black
            )
            contact_style = ParagraphStyle(
                'WradContact',
                parent=styles['Normal'],
                fontName='Helvetica',
                fontSize=9,
                leading=13,
                textColor=text_muted
            )
            meta_right_style = ParagraphStyle(
                'WradMetaRight',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=11,
                leading=15,
                alignment=2,
                textColor=red_wrad
            )
            meta_date_style = ParagraphStyle(
                'WradMetaDate',
                parent=styles['Normal'],
                fontName='Helvetica',
                fontSize=9,
                leading=13,
                alignment=2,
                textColor=text_muted
            )
            section_title = ParagraphStyle(
                'WradSection',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=10,
                leading=14,
                textColor=text_dark,
                spaceAfter=4
            )
            table_header = ParagraphStyle(
                'WradTH',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=9,
                leading=12,
                textColor=colors.white
            )
            table_cell = ParagraphStyle(
                'WradTD',
                parent=styles['Normal'],
                fontName='Helvetica',
                fontSize=9,
                leading=12,
                textColor=text_dark
            )
            table_cell_bold = ParagraphStyle(
                'WradTDBold',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=9,
                leading=12,
                textColor=text_dark
            )
            table_cell_price = ParagraphStyle(
                'WradTDPrice',
                parent=styles['Normal'],
                fontName='Helvetica-Bold',
                fontSize=10,
                leading=13,
                alignment=2,
                textColor=red_wrad
            )

            story = []

            from io import BytesIO
            from reportlab.platypus import Image as RLImage
            try:
                lw = 4.6 * cm
                logo_flowable = RLImage(BytesIO(logo_bytes("noir_jpg")), width=lw, height=lw * 281 / 900)
                logo_flowable.hAlign = "LEFT"
            except Exception:
                logo_flowable = Paragraph("<b>WRAD</b>", title_style)

            # 1. EN-TÊTE ÉPURÉ DE L'ENTREPRISE & COORDONNÉES
            # (Strictement sans slogan 'automotive tinting', sans description commerciale, sans validité de l'offre)
            header_data = [
                [
                    logo_flowable,
                    Paragraph(f"DEVIS N° {devis_num}", meta_right_style)
                ],
                [
                    Paragraph(
                        "Atelier Wrad • Poitiers &amp; alentours (Atelier ou Domicile)<br/>"
                        "Tél : 07 67 60 10 98 • Email : wradauto@gmail.com • Instagram : @wradauto",
                        contact_style
                    ),
                    Paragraph(f"Date : {date_str}", meta_date_style)
                ]
            ]
            t_header = Table(header_data, colWidths=[10 * cm, 7 * cm])
            t_header.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, -1), 'TOP'),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ('TOPPADDING', (0, 0), (-1, -1), 2),
                ('LEFTPADDING', (0, 0), (-1, -1), 0),
                ('RIGHTPADDING', (0, 0), (-1, -1), 0),
                ('TOPPADDING', (0, 1), (-1, 1), 8),
            ]))
            story.append(t_header)
            story.append(Spacer(1, 15))
            story.append(HRFlowable(width="100%", thickness=1, color=border_gray, spaceAfter=15))

            # 2. VÉHICULE CONCERNÉ & CLIENT
            marque = vehicule.get('marque', '')
            modele = vehicule.get('modele', '')
            annee = vehicule.get('annee', '')
            gen = vehicule.get('generation', '')
            veh_str = f"<b>{marque} {modele}</b>" + (f" ({annee})" if annee else "")
            if gen and gen != "Estimé par IA":
                veh_str += f"<br/><font color='#71717A' size='8'>{gen}</font>"

            client_str = f"<b>{client_nom}</b>" if client_nom else "Client Particulier / Professionnel"

            info_data = [
                [
                    Paragraph("<b>COORDONNÉES CLIENT</b>", section_title),
                    Paragraph("<b>VÉHICULE CONCERNÉ</b>", section_title)
                ],
                [
                    Paragraph(f"{client_str}<br/><font color='#71717A'>Pose de films solaires</font>", table_cell),
                    Paragraph(veh_str, table_cell)
                ]
            ]
            if roll_nom:
                info_data.append([
                    Paragraph("", table_cell),
                    Paragraph(f"<font color='#71717A' size='8'>Film : {roll_nom} (Laize {laize_cm:.0f} cm)</font>", table_cell)
                ])

            t_info = Table(info_data, colWidths=[8.5 * cm, 8.5 * cm])
            t_info.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, -1), light_gray),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('TOPPADDING', (0, 0), (-1, -1), 8),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 8),
                ('LEFTPADDING', (0, 0), (-1, -1), 10),
                ('RIGHTPADDING', (0, 0), (-1, -1), 10),
                ('LINEBELOW', (0, 0), (-1, 0), 0.5, border_gray),
            ]))
            story.append(t_info)
            story.append(Spacer(1, 20))

            # 3. TABLEAU DES PRESTATIONS ET MÉTRAGES (CONCENTRÉ SUR L'ESSENTIEL)
            story.append(Paragraph("<b>PRESTATION &amp; TARIFICATION</b>", section_title))

            table_content = [
                [
                    Paragraph("Prestation", table_header),
                    Paragraph("Détails des vitres incluses", table_header),
                    Paragraph("Métrage", table_header),
                    Paragraph("Tarif TTC", table_header)
                ],
                [
                    Paragraph(prestation_title, table_cell_bold),
                    Paragraph(prestation_desc, table_cell),
                    Paragraph(f"{metrage_m:.2f} m", table_cell),
                    Paragraph(f"<b>{prix_ttc:.2f} €</b>", table_cell_price)
                ],
                [
                    Paragraph("<b>TOTAL CONSEILLÉ TTC</b>", table_cell_bold),
                    Paragraph("", table_cell),
                    Paragraph(f"<b>{metrage_m:.2f} m</b>", table_cell_bold),
                    Paragraph(f"<b>{prix_ttc:.2f} € TTC</b>", table_cell_price)
                ]
            ]

            t_presta = Table(table_content, colWidths=[4.3 * cm, 7.0 * cm, 2.2 * cm, 3.5 * cm])
            t_presta.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), dark_bg),
                ('ALIGN', (2, 0), (2, -1), 'CENTER'),
                ('ALIGN', (3, 0), (3, -1), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('TOPPADDING', (0, 0), (-1, -1), 8),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 8),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('GRID', (0, 0), (-1, 1), 0.5, border_gray),
                ('BACKGROUND', (0, 2), (-1, 2), light_gray),
                ('LINEABOVE', (0, 2), (-1, 2), 1.5, dark_bg),
                ('GRID', (0, 2), (-1, 2), 0.5, border_gray),
            ]))
            story.append(t_presta)
            story.append(Spacer(1, 30))

            # 4. BAS DE PAGE ÉPURÉ
            story.append(HRFlowable(width="100%", thickness=0.5, color=border_gray, spaceAfter=8))
            footer_text = Paragraph(
                "<font color='#71717A' size='8'>Atelier WRAD • Poitiers &amp; alentours • 07 67 60 10 98 • wradauto@gmail.com • Devis professionnel épuré</font>",
                ParagraphStyle('Footer', alignment=1, fontName='Helvetica', fontSize=8)
            )
            story.append(footer_text)

            doc.build(story)
            return True
        except ImportError:
            return False
        except Exception as e:
            print(f"[Erreur ReportLab PDF] {e}")
            return False

