def _secret(*names, section=None) -> str:
    try:
        src = st.secrets[section] if section else st.secrets
        for n in names:
            if n in src and str(src[n]).strip():
                return str(src[n]).strip().strip('"').strip("'").replace("\n", "").replace(" ", "")
    except Exception:
        pass
    return ""


def supabase_config() -> Tuple[str, str]:
    url = (_secret("SUPABASE_URL") or _secret("url", section="supabase")
           or os.environ.get("SUPABASE_URL", ""))
    key = (_secret("SUPABASE_KEY", "SUPABASE_ANON_KEY") or _secret("key", section="supabase")
           or os.environ.get("SUPABASE_KEY", "") or os.environ.get("SUPABASE_ANON_KEY", ""))
    return url.rstrip("/"), key


_gem = _secret("GEMINI_API_KEY")
if _gem:
    os.environ["GEMINI_API_KEY"] = _gem


def get_store(url: str, key: str):
    # Volontairement sans st.cache_resource : un objet mis en cache garde l'ancienne classe StoreError
    # après un rechargement du script, et l'erreur n'est alors plus interceptée (plantage rouge).
    if url and key:
        return SupabaseStore(url, key)
    return LocalStore(os.path.join(os.path.dirname(os.path.abspath(__file__)), "donnees_locales"))


store = get_store(*supabase_config())


@st.cache_data(ttl=30, show_spinner="Chargement des données…")
def load_data(cache_key: str = "") -> Dict[str, Any]:
    settings_rows = store.list("settings")
    settings = {**DEFAULT_SETTINGS, **(settings_rows[0] if settings_rows else {})}
    settings.pop("id", None)
    return {
        "clients": [normalize_client(c) for c in store.list("clients")],
        "rolls": [normalize_roll(r) for r in store.list("rouleaux")],
        "vehicles": {v["id"]: v for v in store.list("vehicules")},
        "settings": settings,
    }


def flash(msg: str, kind: str = "success"):
    st.session_state["_flash"] = (msg, kind)


def save(table: str, item: Dict[str, Any], msg: str = "Enregistré dans Supabase ✓") -> bool:
    try:
        store.upsert(table, item)
    except StoreError as e:
        st.error(f"⚠️ NON enregistré : {e}")
        return False
    load_data.clear()
    flash(msg)
    return True


def save_many(table: str, items: List[Dict[str, Any]]) -> bool:
    try:
        store.upsert_many(table, items)
    except StoreError as e:
        st.error(f"⚠️ NON enregistré : {e}")
        return False
    load_data.clear()
    return True


def remove(table: str, item_id: str, msg: str = "Supprimé ✓") -> bool:
    try:
        store.delete(table, item_id)
    except StoreError as e:
        st.error(f"⚠️ Suppression impossible : {e}")
        return False
    load_data.clear()
    flash(msg)
    return True


