def client_form(cid: str):
    existing = next((c for c in CLIENTS if c["id"] == cid), None)
    c = dict(existing) if existing else normalize_client({
        "statut": "Posé", "datePose": today_iso(), "statutPaiement": "Payé", "reglement": "Espèces",
        "rouleauId": ss.get("est_roll_id", "")})
    with st.container(border=True):
        top = st.columns([4, 1])
        top[0].markdown(f"### {'Modifier : ' + c['clientNom'] if existing else 'Nouveau client'}")
        if top[1].button("Fermer", key=f"close_cli_{cid}", width="stretch"):
            ss["edit_client"] = None
            ss["tbl_ver"] += 1
            st.rerun()
        if existing:
            cost = client_cost(c, ROLLS_BY_ID)
            ben = c["prixFactureTTC"] - cost
            st.markdown(f'<div class="wrad-sub">Coût film : <b>{eur(cost)}</b> · Bénéfice : '
                        f'<b style="color:{GREEN if ben >= 0 else RED}">{eur(ben, signed=True)}</b></div>',
                        unsafe_allow_html=True)

        choices = roll_choices(ROLLS)
        roll_labels = ["Aucun rouleau"] + [l for l, _ in choices]
        roll_ids = [""] + [i for _, i in choices]
        packs = PRESTATIONS if c["pack"] in PRESTATIONS else PRESTATIONS + [c["pack"]]

        with st.form(f"form_cli_{cid}", border=False):
            st.markdown("**Client**")
            a, b = st.columns(2)
            cat_opts = CATEGORIES if c.get("categorie") in CATEGORIES or not existing else ["—"] + CATEGORIES
            categorie = a.selectbox("Catégorie *", cat_opts, idx_of(cat_opts, c.get("categorie") or ("D" if not existing else "—")))
            src = b.selectbox("Source", ["—"] + SOURCES, idx_of(["—"] + SOURCES, c["source"]))
            nom = a.text_input("Nom *", c["clientNom"])
            tel = b.text_input("Téléphone", c["telephone"])
            contact = a.text_input("Instagram / e-mail", c["contact"])
            parrain = b.text_input("Parrainé par", c["parrain"])

            st.markdown("**Véhicule & prestation**")
            a, b = st.columns(2)
            veh = a.text_input("Véhicule *", c["vehicule"], placeholder="Ex : Golf 4 noire")
            immat = b.text_input("Immatriculation", c["immatriculation"])
            pack = a.selectbox("Prestation", packs, idx_of(packs, c["pack"]))
            teinte = b.selectbox("Teinte", ["—"] + TEINTES, idx_of(["—"] + TEINTES, c["teinte"]))
            roll_i = a.selectbox("Rouleau utilisé", range(len(roll_labels)), idx_of(roll_ids, c["rouleauId"]),
                                 format_func=lambda i: roll_labels[i])
            metrage = b.number_input("Métrage utilisé (m)", 0.0, 100.0, float(c["metrageUtiliseM"]), 0.1, format="%.2f")

            st.markdown("**Suivi & dates**")
            a, b = st.columns(2)
            statut = a.selectbox("Statut", STATUTS, idx_of(STATUTS, c["statut"]))
            d_devis = b.date_input("Date du devis", to_date(c["dateDevis"]), format="DD/MM/YYYY")
            d_rdv = a.date_input("Date du rendez-vous", to_date(c["dateRdv"]), format="DD/MM/YYYY")
            d_pose = b.date_input("Date de pose", to_date(c["datePose"]), format="DD/MM/YYYY")
            avis = st.checkbox("Avis Google / Instagram demandé", c["avisDemande"])

            st.markdown("**Paiement**")
            a, b, cc = st.columns(3)
            prix = a.number_input("Prix facturé TTC (€)", 0.0, 100000.0, float(c["prixFactureTTC"]), 5.0, format="%.2f")
            regl = b.selectbox("Mode de règlement", ["—"] + REGLEMENTS, idx_of(["—"] + REGLEMENTS, c["reglement"]))
            spay = cc.selectbox("Statut du paiement", STATUTS_PAIEMENT, idx_of(STATUTS_PAIEMENT, c["statutPaiement"]))
            notes = st.text_area("Notes", c["notes"], height=80)

            if st.form_submit_button("Enregistrer", type="primary", width="stretch"):
                if not nom.strip() or not veh.strip():
                    st.error("Le nom et le véhicule sont obligatoires.")
                else:
                    if statut == "Posé" and not d_pose:
                        d_pose = date.today()
                    if statut == "Devis envoyé" and not d_devis:
                        d_devis = date.today()
                    c.update({
                        "clientNom": nom.strip(), "telephone": tel.strip(), "contact": contact.strip(),
                        "source": "" if src == "—" else src, "parrain": parrain.strip(), "vehicule": veh.strip(),
                        "immatriculation": immat.strip().upper(), "pack": pack,
                        "teinte": "" if teinte == "—" else teinte, "rouleauId": roll_ids[roll_i],
                        "metrageUtiliseM": float(metrage), "statut": statut,
                        "dateDevis": d_devis.isoformat() if d_devis else "",
                        "dateRdv": d_rdv.isoformat() if d_rdv else "",
                        "datePose": d_pose.isoformat() if d_pose else "",
                        "avisDemande": bool(avis), "prixFactureTTC": float(prix),
                        "reglement": "" if regl == "—" else regl, "statutPaiement": spay, "notes": notes.strip(),
                        "categorie": "" if categorie == "—" else categorie,
                    })
                    if save("clients", c, f"Fiche de {c['clientNom']} enregistrée ✓"):
                        ss["edit_client"] = None
                        ss["tbl_ver"] += 1
                        st.rerun()

        if existing:
            with st.popover("Supprimer cette fiche"):
                st.write(f"Supprimer définitivement **{c['clientNom']}** ?")
                if st.button("Oui, supprimer", type="primary", key=f"del_cli_{cid}"):
                    if remove("clients", cid, f"{c['clientNom']} supprimé"):
                        ss["edit_client"] = None
                        ss["tbl_ver"] += 1
                        st.rerun()


