def page_dashboard():
    header("Tableau de bord", datetime.now().strftime("Aujourd'hui, %d/%m/%Y"))
    stt = dashboard_stats(CLIENTS, ROLLS, SETTINGS)          # « À faire » : toujours tous les clients
    vue = st.columns([1, 3])[0].selectbox("Chiffre d'affaires", ["CA TOTAL", "CA D", "CA PAD"], key="dash_cat",
                       help="CA TOTAL = clients D + PAD · CA D = seulement les clients D · CA PAD = seulement les clients PAD")
    cat = {"CA D": "D", "CA PAD": "PAD"}.get(vue)
    sel_clients = [c for c in CLIENTS if c.get("categorie") == cat] if cat else CLIENTS
    stf = dashboard_stats(sel_clients, ROLLS, SETTINGS)       # chiffres filtrés selon le menu
    suffix = f" ({cat})" if cat else ""
    k = st.columns(5)
    kpi(k[0], "CA du mois" + suffix, eur(stf["ca_mois"]), f"{stf['nb_mois']} pose(s) ce mois-ci")
    kpi(k[1], vue, eur(stf["ca_total"]), f"panier moyen {eur(stf['panier_moyen'])}", accent=bool(cat))
    kpi(k[2], "Bénéfice (après film)" + suffix, eur(stf["benef_total"]), "CA − coût du film utilisé",
        GREEN if stf["benef_total"] >= 0 else RED)
    kpi(k[3], "Véhicules posés" + suffix, str(stf["nb_poses"]))
    sans_cat = sum(1 for c in CLIENTS if is_done(c) and c.get("categorie") not in CATEGORIES)
    if sans_cat:
        st.caption(f"⚠️ {sans_cat} pose(s) sans catégorie : comptées dans le CA TOTAL seulement. "
                   "Ouvrez ces fiches dans « Clients » pour choisir D ou PAD.")
    tt = stt["taux_transfo"]
    kpi(k[4], "Transformation", f"{round(tt * 100)} %" if tt is not None else "—", "devis → RDV ou pose")

    left, right = st.columns([3, 2])
    with left:
        with st.container(border=True):
            st.markdown("#### À faire")

            def section(title, items, render):
                st.markdown(f'<div class="wrad-tag">{title}</div>', unsafe_allow_html=True)
                if not items:
                    st.markdown('<div class="wrad-muted">Rien pour le moment</div>', unsafe_allow_html=True)
                    return
                for it in items[:6]:
                    c, right_txt, color = render(it)
                    a, b = st.columns([5, 1], vertical_alignment="center")
                    a.markdown(f'<div class="wrad-row"><span>{c["clientNom"]} · {c["vehicule"]}</span>'
                               f'<span style="color:{color};font-weight:600">{right_txt}</span></div>',
                               unsafe_allow_html=True)
                    if b.button("Ouvrir", key=f"open_{title[:6]}_{c['id']}", width="stretch"):
                        goto("Clients", edit_client=c["id"])
                        st.rerun()
                if len(items) > 6:
                    st.markdown(f'<div class="wrad-muted">+ {len(items) - 6} autre(s)</div>', unsafe_allow_html=True)

            section("RENDEZ-VOUS À VENIR", stt["rdv"], lambda c: (c, iso_to_fr(c["dateRdv"]), BLUE))
            section(f"DEVIS À RELANCER (≥ {SETTINGS['delai_relance_jours']} JOURS)", stt["a_relancer"],
                    lambda t: (t[0], f"il y a {t[1]} j", AMBER))
            section("PAIEMENTS À ENCAISSER", stt["a_encaisser"],
                    lambda c: (c, f"{c['statutPaiement']} · {eur(c['prixFactureTTC'])}", RED))
            section("AVIS À DEMANDER", stt["avis"], lambda c: (c, iso_to_fr(c.get("datePose", "")), TEXT_2))

    with right:
        gs = global_roll_stats(ROLLS, CLIENTS)
        with st.container(border=True):
            st.markdown("#### Rouleaux en cours")
            active = [r for r in ROLLS if r["statut"] == "En cours"]
            if not active:
                st.markdown('<div class="wrad-muted">Aucun rouleau en cours. Ajoutez vos achats dans « Rouleaux ».</div>',
                            unsafe_allow_html=True)
            for r in active:
                s = gs["par_rouleau"][r["id"]]
                st.markdown(f"**{roll_title(r)}** <span class='wrad-sub' style='float:right'>{num(s['metres_restants'], 1)} m restants</span>",
                            unsafe_allow_html=True)
                st.progress(s["pct"])
                sub = f"{s['nb_vehicules']} véhicule(s)"
                if s["vehicules_restants"] is not None:
                    sub += f" · ≈ {s['vehicules_restants']} encore possible(s)"
                st.markdown(f'<div class="wrad-muted" style="margin:-8px 0 10px">{sub}</div>', unsafe_allow_html=True)
            if gs["moyenne_vehicules"] is not None:
                st.caption(f"Moyenne : {num(gs['moyenne_vehicules'], 1)} véhicules / rouleau ({gs['moyenne_label']})")
        with st.container(border=True):
            st.markdown("#### D'où viennent vos clients")
            if not stt["sources"]:
                st.markdown('<div class="wrad-muted">Renseignez la « source » dans les fiches clients.</div>',
                            unsafe_allow_html=True)
            total = sum(n for _, n in stt["sources"]) or 1
            for src, n in stt["sources"]:
                st.markdown(f"{src} <span class='wrad-sub' style='float:right'>{n} ({round(n / total * 100)} %)</span>",
                            unsafe_allow_html=True)
                st.progress(n / total)

    with st.container(border=True):
        st.markdown(f"#### Chiffre d'affaires — 6 derniers mois{suffix}")
        import altair as alt
        df = pd.DataFrame(stf["ca_par_mois"], columns=["Mois", "CA"])
        df["ordre"] = range(len(df))
        df["Actuel"] = df["ordre"] == len(df) - 1
        chart = alt.Chart(df).mark_bar(cornerRadiusTopLeft=4, cornerRadiusTopRight=4).encode(
            x=alt.X("Mois:N", sort=list(df["Mois"]), title=None, axis=alt.Axis(labelAngle=0)),
            y=alt.Y("CA:Q", title="€"),
            color=alt.condition("datum.Actuel", alt.value(ACCENT), alt.value("#3f3f46")),
            tooltip=[alt.Tooltip("Mois:N"), alt.Tooltip("CA:Q", format=".2f")],
        ).properties(height=220)
        st.altair_chart(chart, width="stretch")


