def plan_svg(nest: Dict[str, Any], laize_cm: float) -> str:
    total_cm = nest.get("total_linear_cm", 0.0)
    length_cm = max(100.0, total_cm + 10)
    W = 760
    scale = (W - 40) / length_cm
    rh = laize_cm * scale
    H = rh + 90
    x0, y0 = 20, 30
    out = [f'<svg viewBox="0 0 {W} {H:.0f}" width="100%" xmlns="http://www.w3.org/2000/svg" '
           f'style="font-family:sans-serif;max-width:720px">',
           f'<rect x="{x0}" y="{y0}" width="{length_cm * scale:.1f}" height="{rh:.1f}" fill="{SURFACE_2}" stroke="{BORDER}"/>',
           f'<text x="{x0}" y="{y0 - 10}" fill="{TEXT_3}" font-size="17">Laize {laize_cm:.0f} cm</text>']
    for p in nest.get("placed", []):
        px, py = x0 + p["y"] * scale, y0 + p["x"] * scale
        w, h = p["width_on_roll"] * scale, min(p["height_on_laize"], laize_cm) * scale
        if not p.get("fits", True):
            fill, stroke = "#3a1414", RED
        elif p["zone"] == "arriere":
            fill, stroke = "#2b1b1b", ACCENT
        else:
            fill, stroke = "#24242a", TEXT_2
        out.append(f'<rect x="{px + 1:.1f}" y="{py + 1:.1f}" width="{max(0, w - 2):.1f}" height="{max(0, h - 2):.1f}" '
                   f'fill="{fill}" stroke="{stroke}" stroke-width="1.5"/>')
        if w > 80 and h > 44:
            name = str(p["nom"])[:int(w / 10)].replace("&", "&amp;").replace("<", "")
            out.append(f'<text x="{px + w / 2:.1f}" y="{py + h / 2 - 4:.1f}" fill="{TEXT}" font-size="17" text-anchor="middle">{name}</text>')
            out.append(f'<text x="{px + w / 2:.1f}" y="{py + h / 2 + 18:.1f}" fill="{TEXT_2}" font-size="15" text-anchor="middle">'
                       f'{p["raw_h"]:g} × {p["raw_w"]:g}</text>')
    end = x0 + total_cm * scale
    ya = y0 + rh + 22
    out.append(f'<line x1="{x0}" y1="{ya}" x2="{end:.1f}" y2="{ya}" stroke="{ACCENT}" stroke-width="2.5"/>')
    out.append(f'<text x="{max(x0 + 40, (x0 + end) / 2):.1f}" y="{ya + 22}" fill="{ACCENT}" font-size="20" font-weight="bold" '
               f'text-anchor="middle">{num(nest.get("total_linear_m", 0))} m</text>')
    out.append("</svg>")
    return "".join(out)


def set_vitres(vitres, meta, status):
    ss["est_vitres"] = [dict(v, included=v.get("included", True)) for v in vitres]
    ss["est_vitres_cur"] = ss["est_vitres"]
    ss["est_meta"] = meta
    ss["est_status"] = status
    ss["vit_ver"] += 1


def on_roll_change():
    rid = ss.get("est_roll_sel", "")
    r = ROLLS_BY_ID.get(rid)
    ss["est_roll_id"] = rid
    if r:
        ss["est_laize"] = float(r["laize_cm"])
        ss["est_prix_m"] = round(roll_cost_per_m(r), 2)


def vitres_editor(vitres: List[Dict[str, Any]], key: str, with_inclus: bool) -> Tuple[List[Dict[str, Any]], bool]:
    """Tableau des vitres. Renvoie (vitres, une_ligne_a_ete_supprimee). Cocher « Suppr. » retire la vitre."""
    cols = (["Inclus"] if with_inclus else []) + ["Nom", "H (cm)", "L (cm)", "Zone", "Suppr."]
    df = pd.DataFrame([{**({"Inclus": v.get("included", True)} if with_inclus else {}),
                        "Nom": v.get("nom", ""), "H (cm)": float(v.get("hauteur_cm", 0)),
                        "L (cm)": float(v.get("largeur_cm", 0)), "Zone": v.get("zone", "arriere"), "Suppr.": False}
                       for v in vitres], columns=cols)
    cfg = {
        "Nom": st.column_config.TextColumn(width="large", default="Vitre"),
        "H (cm)": st.column_config.NumberColumn("H", width="small", min_value=1, max_value=300, step=1, default=45),
        "L (cm)": st.column_config.NumberColumn("L", width="small", min_value=1, max_value=300, step=1, default=60),
        "Zone": st.column_config.SelectboxColumn(width="small", options=["arriere", "avant"], default="arriere"),
        "Suppr.": st.column_config.CheckboxColumn("🗑 Suppr.", width="small", default=False,
                                                  help="Cochez pour supprimer cette vitre"),
    }
    if with_inclus:
        cfg["Inclus"] = st.column_config.CheckboxColumn("✓", width="small", default=True,
                                                        help="Décochez pour exclure la vitre du calcul sans la supprimer")
    edited = st.data_editor(df, key=key, num_rows="dynamic", width="stretch", hide_index=True, column_config=cfg)
    out, deleted = [], False
    for _, row in edited.iterrows():
        if bool(row.get("Suppr.")) and pd.notna(row.get("Suppr.")):
            deleted = True
            continue
        h, w = to_float(row.get("H (cm)")), to_float(row.get("L (cm)"))
        if h and w:
            inc = row.get("Inclus", True) if with_inclus else True
            out.append({"nom": str(row.get("Nom") or "Vitre"), "hauteur_cm": h, "largeur_cm": w,
                        "zone": row.get("Zone") or "arriere",
                        "included": bool(inc) if pd.notna(inc) else True})
    return out, deleted


def page_estimator():
    header("Estimateur & devis", "Métrage, plan de coupe et prix conseillé par pack")

    with st.container(border=True):
        a, b, c, d, e = st.columns([2, 2, 1, 1.2, 1.6], vertical_alignment="bottom")
        marque = a.text_input("Marque", key="est_marque", placeholder="Peugeot")
        modele = b.text_input("Modèle", key="est_modele", placeholder="208")
        annee = c.text_input("Année", key="est_annee", placeholder="2020")
        if d.button("Estimer", type="primary", width="stretch"):
            if not marque.strip() or not modele.strip():
                st.warning("Renseignez au minimum la marque et le modèle.")
            else:
                key = vehicle_key(marque, modele, annee)
                found = VEHICLES.get(key) or next((v for v in VEHICLES.values()
                                                   if v.get("marque", "").lower() == marque.strip().lower()
                                                   and v.get("modele", "").lower() == modele.strip().lower()), None)
                meta = {"marque": marque.strip(), "modele": modele.strip(), "annee": annee.strip()}
                if found:
                    set_vitres(found.get("vitres", []), found, ("Depuis la base véhicules", "ok"))
                elif os.environ.get("GEMINI_API_KEY"):
                    with st.spinner("Estimation IA…"):
                        try:
                            res = GeminiEstimator.estimate(marque, modele, annee)
                            entry = {**meta, "id": key, "generation": res.get("generation", "Estimé par IA"),
                                     "vitres": res.get("vitres", [])}
                            save("vehicules", entry, "Cotes estimées par IA et mémorisées")
                            set_vitres(entry["vitres"], entry, ("Estimé par IA (à vérifier)", "ok"))
                        except Exception as ex:
                            set_vitres(DEFAULT_VITRES, {**meta, "generation": "Modèle type"},
                                       (f"IA indisponible — cotes types ({ex})", "warn"))
                else:
                    set_vitres(DEFAULT_VITRES, {**meta, "generation": "Modèle type"}, ("Cotes types à mesurer", "warn"))
                st.rerun()
        if e.button("Enregistrer les cotes", width="stretch"):
            if not marque.strip() or not modele.strip():
                st.warning("Marque et modèle nécessaires.")
            else:
                key = vehicle_key(marque, modele, annee)
                gen = ss["est_meta"].get("generation", "")
                if gen in ("", "Modèle type", "Estimé par IA"):
                    gen = "Cotes mesurées"
                save("vehicules", {"id": key, "marque": marque.strip(), "modele": modele.strip(),
                                   "annee": annee.strip(), "generation": gen,
                                   "vitres": [dict(v) for v in ss.get("est_vitres_cur", ss["est_vitres"])]},
                     "Cotes enregistrées ✓")
                st.rerun()
        txt, kind = ss["est_status"]
        st.markdown(f'<div class="wrad-muted" style="color:{GREEN if kind == "ok" else (AMBER if kind == "warn" else TEXT_3)}">{txt}</div>',
                    unsafe_allow_html=True)

        choices = roll_choices(ROLLS, only_active=True)
        ids = [i for _, i in choices] + [""]
        labels = {i: l for l, i in choices}
        labels[""] = "Saisie manuelle"
        if "est_roll_sel" not in ss or ss["est_roll_sel"] not in ids:
            ss["est_roll_sel"] = ids[0]
            on_roll_change()
        ss.setdefault("est_laize", 101.0)
        ss.setdefault("est_prix_m", 8.04)
        if "est_coeff" not in ss:
            ss["est_coeff"] = float(SETTINGS["coeff_prix"])
        a, b, c, d = st.columns([3, 1, 1, 1])
        a.selectbox("Rouleau utilisé pour le calcul", ids, key="est_roll_sel", format_func=lambda i: labels[i],
                    on_change=on_roll_change)
        laize = b.number_input("Laize (cm)", 20.0, 200.0, key="est_laize", step=1.0)
        prix_m = c.number_input("Prix du mètre (€)", 0.0, 200.0, key="est_prix_m", step=0.1, format="%.2f")
        coeff = d.number_input("Coefficient", 0.1, 20.0, key="est_coeff", step=0.1, format="%.2f")

    with st.container(border=True):
            st.markdown("#### Vitres du véhicule")
            vitres, deleted = vitres_editor(ss["est_vitres"], f"vitres_{ss['vit_ver']}", with_inclus=True)
            st.caption("H = hauteur (sur la laize) · L = largeur (sur la longueur). "
                       "Ajouter : ligne vide en bas du tableau · Supprimer : cochez « 🗑 Suppr. ».")
            ss["est_vitres_cur"] = vitres          # état courant (la base ne change qu'au chargement / suppression)
            if deleted:
                ss["est_vitres"] = vitres
                ss["vit_ver"] += 1
                st.rerun()

    marge = float(SETTINGS.get("marge_coupe_cm", 5.0))
    results, nest_tot = {}, None
    for k, vs in (("arriere", [v for v in vitres if v["zone"] == "arriere"]),
                  ("avant", [v for v in vitres if v["zone"] == "avant"]), ("total", vitres)):
        nest = StrictHorizontalNestingEngine.compute(vs, laize, marge)
        m = nest["total_linear_m"]
        results[k] = {"m": m, "cost": m * prix_m, "prix": m * prix_m * coeff}
        if k == "total":
            nest_tot = nest

    if True:
        p = st.columns(3)
        for col, (k, t) in zip(p, (("arriere", "3/4 arrière"), ("avant", "Vitres avant"), ("total", "Véhicule complet"))):
            kpi(col, t, eur(results[k]["prix"]).replace(",00", ""),
                f"{num(results[k]['m'])} m · film {eur(results[k]['cost'])}", accent=(k == "total"))
        with st.container(border=True):
            warn = nest_tot.get("has_seam_warning")
            st.markdown(f"**Plan de coupe** <span class='wrad-sub'>· véhicule complet · rendement "
                        f"{num(nest_tot.get('efficiency_pct', 0), 0)} %</span>"
                        + (f" <span style='color:{RED}'>· raccord nécessaire</span>" if warn else ""),
                        unsafe_allow_html=True)
            st.markdown(plan_svg(nest_tot, laize), unsafe_allow_html=True)

    # ---------------- Devis
    st.markdown("### Devis")
    with st.container(border=True):
        titles = {
            "arriere": ("PACK 3/4 ARRIÈRE", "Lunette arrière + vitres latérales arrière + custodes arrière", "Pack 3/4 arrière"),
            "avant": ("PACK VITRES AVANT", "Vitres latérales avant + custodes avant", "Pack vitres avant"),
            "total": ("VÉHICULE COMPLET", "Lunette arrière + latérales arrière + custodes + vitres avant", "Véhicule complet"),
        }
        pk = st.radio("Prestation", ["arriere", "avant", "total"], horizontal=True,
                      format_func=lambda k: titles[k][0].title(), key="devis_pack")
        pack_title, desc, pack_crm = titles[pk]
        a, b, c = st.columns(3)
        d_nom = a.text_input("Client", key="devis_nom")
        d_tel = b.text_input("Téléphone", key="devis_tel")
        d_src = c.selectbox("Source du contact", SOURCES, key="devis_src")
        d_cat = c.selectbox("Catégorie", CATEGORIES, key="devis_cat")
        a, b, c = st.columns(3)
        d_teinte = a.selectbox("Teinte proposée", TEINTES, index=1, key="devis_teinte")
        d_prix = b.number_input("Prix TTC", 0.0, 100000.0, float(round(results[pk]["prix"])), 5.0, format="%.2f",
                                key=f"devis_prix_{pk}_{round(results[pk]['prix'])}")
        c.markdown(f"<div class='wrad-muted' style='padding-top:34px'>Métrage estimé : {num(results[pk]['m'])} m</div>",
                   unsafe_allow_html=True)

        mq, md, an = ss.get("est_marque", ""), ss.get("est_modele", ""), ss.get("est_annee", "")
        num_devis = f"WRAD-{datetime.now().strftime('%Y%m%d-%H%M')}"
        full_desc = f"{desc} — Teinte {d_teinte}"
        r = ROLLS_BY_ID.get(ss.get("est_roll_id", ""))
        film_nom = roll_title(r) if r else ""
        from xml.sax.saxutils import escape
        buf = io.BytesIO()
        veh = {"marque": escape(mq), "modele": escape(md), "annee": escape(an),
               "generation": escape(ss["est_meta"].get("generation", ""))}
        WradPDFGenerator.generate_pdf(buf, num_devis, date.today().strftime("%d/%m/%Y"), veh, pack_title,
                                      escape(full_desc), results[pk]["m"], d_prix, escape(film_nom), laize,
                                      escape(d_nom.strip()))
        a, b = st.columns(2)
        a.download_button("Télécharger le devis PDF", buf.getvalue(), f"Devis_{num_devis}.pdf", "application/pdf",
                          type="primary", width="stretch", disabled=not buf.getvalue())
        if b.button("Ajouter au suivi clients (« Devis envoyé »)", width="stretch"):
            if not d_nom.strip():
                st.warning("Indiquez le nom du client.")
            else:
                cl = normalize_client({
                    "clientNom": d_nom.strip(), "telephone": d_tel.strip(), "vehicule": f"{mq} {md} {an}".strip(),
                    "pack": pack_crm, "teinte": d_teinte, "rouleauId": ss.get("est_roll_id", ""),
                    "metrageUtiliseM": results[pk]["m"], "prixFactureTTC": d_prix, "statut": "Devis envoyé",
                    "statutPaiement": "À encaisser", "source": d_src, "dateDevis": today_iso(), "categorie": d_cat,
                    "notes": f"Devis {num_devis}"})
                if save("clients", cl, f"{cl['clientNom']} ajouté aux clients (Devis envoyé)"):
                    st.rerun()
        st.caption("Texte à copier dans un message Instagram / SMS (bouton de copie en haut à droite du bloc) :")
        st.code(f"Devis WRAD — {pack_title.title()}\nVéhicule : {mq} {md} {an}\n{full_desc}\n"
                f"Prix : {eur(d_prix)} TTC\n\nWRAD · Poitiers & alentours · 07 67 60 10 98 · @wradauto", language=None)


