def page_clients():
    header("Clients", "Toutes vos prestations, devis et prospects — « Ouvrir » pour voir ou modifier une fiche")
    a, b, c = st.columns([3, 1.3, 1.3], vertical_alignment="bottom")
    q = a.text_input("Rechercher", placeholder="Nom, véhicule, téléphone, immatriculation…", label_visibility="collapsed")
    if b.button("＋ Nouveau client", type="primary", width="stretch"):
        ss["edit_client"] = "__new__" + new_id("cli")
        st.rerun()
    c.download_button("Exporter les recettes (CSV)", livre_recettes_csv(CLIENTS, ROLLS),
                      f"Wrad_recettes_{date.today().isoformat()}.csv", "text/csv", width="stretch")
    a, b = st.columns([4, 1], vertical_alignment="bottom")
    flt = a.segmented_control("Statut", ["Tous"] + STATUTS, default="Tous", label_visibility="collapsed") or "Tous"
    fcat = b.selectbox("Catégorie", ["Toutes", "D", "PAD"], label_visibility="collapsed")

    if ss["edit_client"]:
        cid = ss["edit_client"]
        client_dialog(cid.replace("__new__", "") if cid.startswith("__new__") else cid)

    rows = []
    for c in CLIENTS:
        if flt != "Tous" and c["statut"] != flt:
            continue
        if fcat != "Toutes" and c.get("categorie") != fcat:
            continue
        hay = " ".join([c["clientNom"], c["vehicule"], c["telephone"], c["contact"], c["immatriculation"], c["notes"]]).lower()
        if q and q.lower() not in hay:
            continue
        rows.append(c)
    rows.sort(key=lambda c: c.get("datePose") or c.get("dateRdv") or c.get("dateDevis") or "", reverse=True)

    if not rows:
        st.info("Aucun client pour ces critères. Cliquez sur « ＋ Nouveau client » pour en ajouter un.")
        return
    total = sum(c["prixFactureTTC"] for c in rows if is_done(c))
    st.caption(f"{len(rows)} fiche(s) · {eur(total)} facturés (poses)")
    limit = ss.get("cli_limit", 40)
    for c in rows[:limit]:
        d_aff = iso_to_fr(c.get("datePose") or c.get("dateRdv") or c.get("dateDevis") or "")
        cat = c.get("categorie") or "—"
        cat_html = (f'<span class="wrad-pill" style="color:{TEXT};background:{SURFACE_2};border:1px solid {BORDER}">{cat}</span>')
        regl = (c["statutPaiement"] if c["statut"] == "Posé" and c["statutPaiement"] != "Payé" else (c["reglement"] or ""))
        regl_html = f' · <span style="color:{AMBER if regl in ("À encaisser", "Acompte versé") else TEXT_3}">{regl}</span>' if regl else ""
        x, y = st.columns([6, 1], vertical_alignment="center")
        x.markdown(
            f'<div class="wrad-row" style="align-items:center;flex-wrap:wrap">'
            f'<span><b>{c["clientNom"]}</b> · {c["vehicule"]}<br>'
            f'<span class="wrad-muted">{d_aff} · {c["pack"]}{(" · " + c["teinte"]) if c.get("teinte") else ""}{regl_html}</span></span>'
            f'<span style="display:flex;gap:8px;align-items:center">{cat_html} {pill(c["statut"])} '
            f'<b>{eur(c["prixFactureTTC"])}</b></span></div>', unsafe_allow_html=True)
        if y.button("Ouvrir", key=f"cli_open_{c['id']}", width="stretch"):
            ss["edit_client"] = c["id"]
            st.rerun()
    if len(rows) > limit:
        if st.button(f"Afficher plus ({len(rows) - limit} restantes)"):
            ss["cli_limit"] = limit + 40
            st.rerun()


