def roll_form(rid: str):
    existing = ROLLS_BY_ID.get(rid)
    r = dict(existing) if existing else normalize_roll({"id": rid, "date_achat": today_iso(), "fournisseur": "Leaderfilm"})
    with st.container(border=True):
        st.markdown(f"### {'Modifier le rouleau' if existing else 'Nouveau rouleau acheté'}")
        with st.form(f"form_roll_{rid}", border=False):
            a, b = st.columns(2)
            marques = MARQUES_FILM if r["marque"] in MARQUES_FILM else MARQUES_FILM + [r["marque"]]
            marque = a.selectbox("Marque du film", marques, idx_of(marques, r["marque"]))
            autre = b.text_input("Autre marque (si « Autre »)", "" if r["marque"] in MARQUES_FILM else r["marque"])
            ref = a.text_input("Référence (facultatif)", r["reference"])
            teinte = b.selectbox("Teinte", ["—"] + TEINTES, idx_of(["—"] + TEINTES, r["teinte"]))
            lz = a.number_input("Laize (cm)", 10.0, 300.0, float(r["laize_cm"] or 101), 1.0)
            lg = b.number_input("Longueur (m)", 1.0, 500.0, float(r["longueur_m"] or 30), 1.0)
            px = a.number_input("Prix d'achat TTC (€)", 0.0, 10000.0, float(r["prix_achat_ttc"]), 1.0, format="%.2f")
            da = b.date_input("Date d'achat", to_date(r["date_achat"]) or date.today(), format="DD/MM/YYYY")
            four = a.text_input("Fournisseur", r["fournisseur"])
            stat = b.selectbox("Statut", ["En cours", "Terminé"], idx_of(["En cours", "Terminé"], r["statut"]))
            df_ = b.date_input("Date de fin (si terminé)", to_date(r["date_fin"]), format="DD/MM/YYYY")
            notes = a.text_input("Notes", r["notes"])
            c1, c2 = st.columns(2)
            ok = c1.form_submit_button("Enregistrer", type="primary", width="stretch")
            cancel = c2.form_submit_button("Annuler", width="stretch")
        if cancel:
            ss["edit_roll"] = None
            st.rerun()
        if ok:
            m = autre.strip() if marque == "Autre" and autre.strip() else marque
            r.update({"marque": m, "reference": ref.strip(), "teinte": "" if teinte == "—" else teinte,
                      "laize_cm": float(lz), "longueur_m": float(lg), "prix_achat_ttc": float(px),
                      "date_achat": da.isoformat() if da else "", "fournisseur": four.strip(), "statut": stat,
                      "date_fin": (df_ or date.today()).isoformat() if stat == "Terminé" else "", "notes": notes.strip()})
            if save("rouleaux", r, f"Rouleau {roll_title(r)} enregistré ✓"):
                ss["edit_roll"] = None
                st.rerun()


def page_rolls():
    header("Rouleaux", "Vos achats de film, leur coût réel et leur rendement")
    if st.button("＋ Rouleau acheté", type="primary"):
        ss["edit_roll"] = new_id("rlx")
        st.rerun()
    gs = global_roll_stats(ROLLS, CLIENTS)
    k = st.columns(5)
    kpi(k[0], "Véhicules / rouleau", num(gs["moyenne_vehicules"], 1) if gs["moyenne_vehicules"] is not None else "—",
        gs["moyenne_label"])
    kpi(k[1], "Métrage moyen / véhicule", f"{num(gs['metrage_moyen'])} m" if gs["metrage_moyen"] is not None else "—",
        "poses liées à un rouleau")
    kpi(k[2], "Coût film / véhicule", eur(gs["cout_moyen_vehicule"]), "prix du rouleau / véhicules")
    kpi(k[3], "Prix moyen du mètre", eur(gs["prix_m_moyen"]), "tous achats confondus")
    kpi(k[4], "Dépenses en film", eur(gs["depenses"]), f"{len(ROLLS)} rouleau(x) acheté(s)")

    if ss["edit_roll"]:
        roll_form(ss["edit_roll"])

    if not ROLLS:
        st.info("Ajoutez chaque rouleau que vous achetez (prix, date). À chaque pose, indiquez le rouleau utilisé : "
                "vous saurez combien de véhicules vous faites par rouleau et ce que coûte réellement le film par voiture.")
        return
    ordered = sorted(ROLLS, key=lambda r: r.get("date_achat") or "", reverse=True)
    ordered.sort(key=lambda r: r["statut"] != "En cours")
    for r in ordered:
        s = gs["par_rouleau"][r["id"]]
        with st.container(border=True):
            a, b = st.columns([3, 2], vertical_alignment="center")
            a.markdown(f"#### {roll_title(r)} &nbsp; {pill(r['statut'])}", unsafe_allow_html=True)
            info = f"Acheté le {iso_to_fr(r['date_achat']) or '—'}"
            if r.get("fournisseur"):
                info += f" chez {r['fournisseur']}"
            info += f" · {r['laize_cm']:.0f} cm × {r['longueur_m']:g} m · {eur(r['prix_achat_ttc'])} ({eur(s['cout_m'])}/m)"
            if r["statut"] == "Terminé" and r.get("date_fin"):
                info += f" · terminé le {iso_to_fr(r['date_fin'])}"
            a.markdown(f'<div class="wrad-sub" style="margin-top:-8px">{info}</div>', unsafe_allow_html=True)
            b1, b2, b3 = b.columns(3)
            if b1.button("Terminé" if r["statut"] == "En cours" else "Rouvrir", key=f"tg_{r['id']}", width="stretch"):
                r2 = dict(r)
                if r["statut"] == "En cours":
                    r2.update({"statut": "Terminé", "date_fin": today_iso()})
                else:
                    r2.update({"statut": "En cours", "date_fin": ""})
                if save("rouleaux", r2, "Statut du rouleau mis à jour"):
                    st.rerun()
            if b2.button("Modifier", key=f"ed_{r['id']}", width="stretch"):
                ss["edit_roll"] = r["id"]
                st.rerun()
            with b3.popover("Suppr.", width="stretch"):
                n = sum(1 for c in CLIENTS if c.get("rouleauId") == r["id"])
                st.write(f"Supprimer **{roll_title(r)}** ?" + (f" {n} fiche(s) y sont liées." if n else ""))
                if st.button("Oui, supprimer", key=f"dl_{r['id']}", type="primary"):
                    if remove("rouleaux", r["id"]):
                        st.rerun()
            st.progress(s["pct"], text=f"{num(s['metres_utilises'], 1)} m utilisés · {num(s['metres_restants'], 1)} m restants")
            m1, m2, m3 = st.columns(3)
            kpi(m1, "Véhicules posés", str(s["nb_vehicules"]))
            kpi(m2, "Coût film / véhicule", eur(s["cout_reel_par_vehicule"]),
                "estimé (rouleau en cours)" if r["statut"] == "En cours" else "réel (rouleau terminé)")
            if r["statut"] == "En cours":
                kpi(m3, "Encore possibles", f"≈ {s['vehicules_restants']}" if s["vehicules_restants"] is not None else "—",
                    "véhicules avec le reste")
            else:
                kpi(m3, "CA − prix du rouleau", eur(s["resultat"], signed=True), "",
                    GREEN if s["resultat"] >= 0 else RED)


