def vehicle_form(key: str):
    v = VEHICLES.get(key, {}) if key != "__new__" else {}
    rows_key = f"veh_rows_{key}"
    if rows_key not in ss:
        ss[rows_key] = [dict(x) for x in (v.get("vitres") or DEFAULT_VITRES)]
        ss["veh_ver"] = ss.get("veh_ver", 0) + 1

    def close():
        ss.pop(rows_key, None)
        ss["edit_vehicle"] = None

    with st.container(border=True):
        st.markdown(f"### {'Modifier le véhicule' if v else 'Nouveau véhicule'}")
        a, b, c, d = st.columns(4)
        marque = a.text_input("Marque *", v.get("marque", ""), key=f"vm_{key}")
        modele = b.text_input("Modèle *", v.get("modele", ""), key=f"vmo_{key}")
        annee = c.text_input("Année", v.get("annee", ""), key=f"va_{key}")
        gen = d.text_input("Génération", v.get("generation", ""), key=f"vg_{key}")
        vitres, deleted = vitres_editor(ss[rows_key], f"veh_ed_{key}_{ss['veh_ver']}", with_inclus=False)
        if deleted:
            ss[rows_key] = vitres
            ss["veh_ver"] += 1
            st.rerun()
        st.caption("Ajouter une vitre : ligne vide en bas du tableau · Supprimer : cochez « 🗑 Suppr. ».")
        c1, c2 = st.columns(2)
        if c2.button("Annuler", key=f"vcancel_{key}", width="stretch"):
            close()
            st.rerun()
        if c1.button("Enregistrer", key=f"vsave_{key}", type="primary", width="stretch"):
            if not marque.strip() or not modele.strip() or not vitres:
                st.error("Marque, modèle et au moins une vitre sont obligatoires.")
                return
            nk = vehicle_key(marque, modele, annee)
            if save("vehicules", {"id": nk, "marque": marque.strip(), "modele": modele.strip(), "annee": annee.strip(),
                                  "generation": gen.strip(), "vitres": vitres}, "Véhicule enregistré ✓"):
                if key not in ("__new__", nk):
                    remove("vehicules", key, "Véhicule enregistré ✓")
                close()
                st.rerun()


def page_vehicles():
    header("Véhicules", "Cotes des vitres enregistrées")
    a, b = st.columns([3, 1], vertical_alignment="bottom")
    q = a.text_input("Rechercher", placeholder="Marque, modèle…", label_visibility="collapsed")
    if b.button("＋ Ajouter un véhicule", type="primary", width="stretch"):
        ss.pop("veh_rows___new__", None)
        ss["edit_vehicle"] = "__new__"
        st.rerun()
    if ss["edit_vehicle"]:
        vehicle_form(ss["edit_vehicle"])
    items = [(k, v) for k, v in VEHICLES.items()
             if not q or q.lower() in f"{v.get('marque', '')} {v.get('modele', '')} {v.get('annee', '')}".lower()]
    items.sort(key=lambda kv: (kv[1].get("marque", "").lower(), kv[1].get("modele", "").lower()))
    if not items:
        st.info("Aucun véhicule. Mesurez une voiture dans l'estimateur puis cliquez sur « Enregistrer les cotes ».")
    for k, v in items:
        with st.container(border=True):
            a, b, c, d = st.columns([5, 1, 1, 1], vertical_alignment="center")
            a.markdown(f"**{v.get('marque', '')} {v.get('modele', '')}**" + (f" ({v['annee']})" if v.get("annee") else "")
                       + f"<br><span class='wrad-muted'>{v.get('generation') or 'Standard'} · {len(v.get('vitres', []))} vitres</span>",
                       unsafe_allow_html=True)
            if b.button("Charger", key=f"ld_{k}", type="primary", width="stretch"):
                ss["est_marque"], ss["est_modele"], ss["est_annee"] = v.get("marque", ""), v.get("modele", ""), v.get("annee", "")
                set_vitres(v.get("vitres", []), v, ("Depuis la base véhicules", "ok"))
                goto("Estimateur & devis")
                st.rerun()
            if c.button("Modifier", key=f"mv_{k}", width="stretch"):
                ss.pop(f"veh_rows_{k}", None)
                ss["edit_vehicle"] = k
                st.rerun()
            with d.popover("Suppr.", width="stretch"):
                if st.button("Oui, supprimer", key=f"dv_{k}", type="primary"):
                    if remove("vehicules", k):
                        st.rerun()


