# PAGE : RÉGLAGES (+ récupération des anciennes données)
# =============================================================================
PACK_ALIASES = {"pack 3/4 arrière": "Pack 3/4 arrière", "pack vitres avant": "Pack vitres avant",
                "véhicule complet": "Véhicule complet"}


def migrate_old_tables() -> Tuple[int, int]:
    """Copie les tables de l'ancienne version (clients, vehicles) vers les nouvelles. Sans effet sur les anciennes."""
    def safe_raw(name):
        try:
            return store.raw_list(name)
        except StoreError:
            return []           # table absente : rien à récupérer
    old_clients = safe_raw("clients")
    new_clients = []
    for c in old_clients:
        prix = float(c.get("prixFactureTTC") or c.get("prix_facture_ttc") or 0)
        pack = str(c.get("pack") or "")
        new_clients.append(normalize_client({
            "id": str(c.get("id")),
            "clientNom": c.get("clientNom") or c.get("client_nom") or "Client",
            "vehicule": c.get("vehicule", ""),
            "datePose": (c.get("datePose") or c.get("date_pose") or "")[:10],
            "pack": PACK_ALIASES.get(pack.lower(), pack or PRESTATIONS[0]),
            "metrageUtiliseM": float(c.get("metrageUtiliseM") or c.get("metrage_utilise_m") or 0),
            "prixFactureTTC": prix,
            "coutRevientTTC": float(c.get("coutRevientTTC") or c.get("cout_revient_ttc") or 0),
            "notes": c.get("notes") or "", "statut": "Posé", "statutPaiement": "Payé",
        }))
    old_veh = safe_raw("vehicles")
    new_veh = []
    for v in old_veh:
        vit = v.get("vitres") or []
        if isinstance(vit, str):
            try:
                vit = json.loads(vit)
            except Exception:
                vit = []
        k = v.get("key") or v.get("id")
        if k:
            new_veh.append({"id": str(k), "marque": v.get("marque", ""), "modele": v.get("modele", ""),
                            "annee": v.get("annee", "") or "", "generation": v.get("generation", "") or "", "vitres": vit})
    already = {c["id"] for c in CLIENTS}
    new_clients = [c for c in new_clients if c["id"] not in already]   # ne jamais écraser une fiche déjà modifiée
    save_many("clients", new_clients)
    save_many("vehicules", [v for v in new_veh if v["id"] not in VEHICLES])
    return len(new_clients), len([v for v in new_veh if v["id"] not in VEHICLES])


def page_settings():
    header("Réglages", "Calcul des prix, sauvegarde et récupération des données")
    with st.container(border=True):
        st.markdown("#### Calcul")
        with st.form("settings"):
            a, b, c = st.columns(3)
            coeff = a.number_input("Coefficient de prix (coût film × coeff)", 0.1, 20.0, float(SETTINGS["coeff_prix"]), 0.1)
            marge = b.number_input("Marge de coupe par vitre (cm)", 0.0, 30.0, float(SETTINGS["marge_coupe_cm"]), 0.5)
            rel = c.number_input("Relancer un devis après (jours)", 1, 60, int(SETTINGS["delai_relance_jours"]), 1)
            if st.form_submit_button("Enregistrer", type="primary"):
                if save("settings", {"id": "settings", "coeff_prix": coeff, "marge_coupe_cm": marge,
                                     "delai_relance_jours": int(rel)}, "Réglages enregistrés ✓"):
                    ss["est_coeff"] = float(coeff)
                    st.rerun()

    with st.container(border=True):
        st.markdown("#### Connexion Supabase")
        if store.is_cloud:
            problems = store.check()
            if problems:
                for p in problems:
                    st.error(p)
            else:
                st.success("Connecté : les 4 tables Wrad sont présentes. Chaque modification est enregistrée immédiatement dans Supabase.")
        else:
            st.error("Supabase non configuré (mode local).")
        st.markdown(f'<div class="wrad-muted">Estimation IA Gemini : {"active" if os.environ.get("GEMINI_API_KEY") else "inactive (GEMINI_API_KEY absente des Secrets)"}'
                    f' · Mot de passe : {"actif" if APP_PASSWORD else "<b style=color:#fbbf24>aucun (ajoutez APP_PASSWORD dans les Secrets)</b>"}</div>',
                    unsafe_allow_html=True)

    with st.container(border=True):
        st.markdown("#### Récupérer les données de l'ancienne version")
        st.markdown('<div class="wrad-sub">Copie vos anciennes fiches clients et véhicules (tables <code>clients</code> et '
                    '<code>vehicles</code>) dans la nouvelle version. Les anciennes tables ne sont ni modifiées ni supprimées, '
                    'et une fiche déjà présente n\'est jamais écrasée : vous pouvez cliquer plusieurs fois sans risque. '
                    'Les anciens « rouleaux » étaient des formats, pas des achats : ils ne sont pas repris.</div>',
                    unsafe_allow_html=True)
        if st.button("Récupérer les anciennes données", disabled=not store.is_cloud):
            try:
                n1, n2 = migrate_old_tables()
                flash(f"{n1} client(s) et {n2} véhicule(s) récupérés")
                st.rerun()
            except StoreError as e:
                st.error(f"Récupération impossible : {e}")

        st.markdown("**Ou importer les fichiers de la version PC** (clients.json, rouleaux.json, database.json)")
        files = st.file_uploader("Fichiers JSON", type="json", accept_multiple_files=True, label_visibility="collapsed")
        if files and st.button("Importer ces fichiers"):
            nc = nr = nv = 0
            for f in files:
                try:
                    data = json.loads(f.getvalue().decode("utf-8"))
                except Exception:
                    st.error(f"{f.name} : fichier illisible")
                    continue
                if f.name.startswith("clients") and isinstance(data, list):
                    items = [normalize_client(c) for c in data]
                    nc += len(items) if save_many("clients", items) else 0
                elif f.name.startswith("rouleaux") and isinstance(data, list):
                    items = [normalize_roll(r) for r in data]
                    nr += len(items) if save_many("rouleaux", items) else 0
                elif isinstance(data, dict):
                    items = [{**v, "id": k} for k, v in data.items() if isinstance(v, dict)]
                    nv += len(items) if save_many("vehicules", items) else 0
            flash(f"Importé : {nc} client(s), {nr} rouleau(x), {nv} véhicule(s)")
            st.rerun()

    with st.container(border=True):
        st.markdown("#### Sauvegarde de secours")
        st.markdown('<div class="wrad-sub">Téléchargez de temps en temps une copie complète de vos données (fichier JSON).</div>',
                    unsafe_allow_html=True)
        dump = json.dumps({"date": datetime.now().isoformat(), "clients": CLIENTS, "rouleaux": ROLLS,
                           "vehicules": VEHICLES, "settings": SETTINGS}, ensure_ascii=False, indent=1)
        st.download_button("Télécharger la sauvegarde", dump.encode("utf-8"),
                           f"wrad_sauvegarde_{date.today().isoformat()}.json", "application/json")


